void types::user::serialize(TlWriter& tlw) const {
    tlw.write_uint32(kId);
    {
        std::uint32_t flags_v = 0;
        if (self) flags_v |= (1u << 10);
        if (contact) flags_v |= (1u << 11);
        if (mutual_contact) flags_v |= (1u << 12);
        if (deleted) flags_v |= (1u << 13);
        if (bot) flags_v |= (1u << 14);
        if (bot_chat_history) flags_v |= (1u << 15);
        if (bot_nochats) flags_v |= (1u << 16);
        if (verified) flags_v |= (1u << 17);
        if (restricted) flags_v |= (1u << 18);
        if (min_) flags_v |= (1u << 20);
        if (bot_inline_geo) flags_v |= (1u << 21);
        if (support) flags_v |= (1u << 23);
        if (scam) flags_v |= (1u << 24);
        if (apply_min_photo) flags_v |= (1u << 25);
        if (fake) flags_v |= (1u << 26);
        if (bot_attach_menu) flags_v |= (1u << 27);
        if (premium) flags_v |= (1u << 28);
        if (attach_menu_enabled) flags_v |= (1u << 29);
        if (access_hash.has_value()) flags_v |= (1u << 0);
        if (first_name.has_value()) flags_v |= (1u << 1);
        if (last_name.has_value()) flags_v |= (1u << 2);
        if (username.has_value()) flags_v |= (1u << 3);
        if (phone.has_value()) flags_v |= (1u << 4);
        if (photo.has_value()) flags_v |= (1u << 5);
        if (status.has_value()) flags_v |= (1u << 6);
        if (bot_info_version.has_value()) flags_v |= (1u << 14);
        if (restriction_reason.has_value()) flags_v |= (1u << 18);
        if (bot_inline_placeholder.has_value()) flags_v |= (1u << 19);
        if (lang_code.has_value()) flags_v |= (1u << 22);
        if (emoji_status.has_value()) flags_v |= (1u << 30);
        tlw.write_uint32(flags_v);
    }
    {
        std::uint32_t flags_v = 0;
        if (bot_can_edit) flags_v |= (1u << 1);
        if (close_friend) flags_v |= (1u << 2);
        if (stories_hidden) flags_v |= (1u << 3);
        if (stories_unavailable) flags_v |= (1u << 4);
        if (contact_require_premium) flags_v |= (1u << 10);
        if (bot_business) flags_v |= (1u << 11);
        if (bot_has_main_app) flags_v |= (1u << 13);
        if (bot_forum_view) flags_v |= (1u << 16);
        if (bot_forum_can_manage_topics) flags_v |= (1u << 17);
        if (bot_can_manage_bots) flags_v |= (1u << 18);
        if (bot_guestchat) flags_v |= (1u << 19);
        if (bot_guard) flags_v |= (1u << 20);
        if (usernames.has_value()) flags_v |= (1u << 0);
        if (stories_max_id.has_value()) flags_v |= (1u << 5);
        if (color.has_value()) flags_v |= (1u << 8);
        if (profile_color.has_value()) flags_v |= (1u << 9);
        if (bot_active_users.has_value()) flags_v |= (1u << 12);
        if (bot_verification_icon.has_value()) flags_v |= (1u << 14);
        if (send_paid_messages_stars.has_value()) flags_v |= (1u << 15);
        if (linked_community_id.has_value()) flags_v |= (1u << 21);
        tlw.write_uint32(flags_v);
    }
    tlw.write_int64(id);
    if (access_hash.has_value()) { tlw.write_int64(access_hash.value()); }
    if (first_name.has_value()) { tlw.write_string(first_name.value()); }
    if (last_name.has_value()) { tlw.write_string(last_name.value()); }
    if (username.has_value()) { tlw.write_string(username.value()); }
    if (phone.has_value()) { tlw.write_string(phone.value()); }
    if (photo.has_value()) { photo.value()->serialize(tlw); }
    if (status.has_value()) { status.value()->serialize(tlw); }
    if (bot_info_version.has_value()) { tlw.write_int32(bot_info_version.value()); }
    if (restriction_reason.has_value()) { tl::write_vector(tlw, restriction_reason.value(), [&](TlWriter& tlw14, const auto& e14) { e14->serialize(tlw14); }); }
    if (bot_inline_placeholder.has_value()) { tlw.write_string(bot_inline_placeholder.value()); }
    if (lang_code.has_value()) { tlw.write_string(lang_code.value()); }
    if (emoji_status.has_value()) { emoji_status.value()->serialize(tlw); }
    if (usernames.has_value()) { tl::write_vector(tlw, usernames.value(), [&](TlWriter& tlw15, const auto& e15) { e15->serialize(tlw15); }); }
    if (stories_max_id.has_value()) { stories_max_id.value()->serialize(tlw); }
    if (color.has_value()) { color.value()->serialize(tlw); }
    if (profile_color.has_value()) { profile_color.value()->serialize(tlw); }
    if (bot_active_users.has_value()) { tlw.write_int32(bot_active_users.value()); }
    if (bot_verification_icon.has_value()) { tlw.write_int64(bot_verification_icon.value()); }
    if (send_paid_messages_stars.has_value()) { tlw.write_int64(send_paid_messages_stars.value()); }
    if (linked_community_id.has_value()) { tlw.write_int64(linked_community_id.value()); }
}

